pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes memory data, uint256 deadline) internal {
        vm.assume(deadline >= block.timestamp);
        uint256 totalBefore;
        try c.totalSupply() returns (uint256 __r) { totalBefore = __r; } catch { return; }
        uint256 callerBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { callerBefore = __r; } catch { return; }
        vm.assume(shareAmount <= callerBefore);
        bool reverted;
        uint256 baseOut;
        uint256 quoteOut;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) returns (uint256 b, uint256 q) {
            reverted = false;
            baseOut = b;
            quoteOut = q;
        } catch {
            reverted = true;
            baseOut = 0;
            quoteOut = 0;
        }
        uint256 totalAfter;
        try c.totalSupply() returns (uint256 __r) { totalAfter = __r; } catch { return; }
        uint256 callerAfter;
        try c.balanceOf(address(this)) returns (uint256 __r) { callerAfter = __r; } catch { return; }
        assertTrue(reverted || (callerBefore - callerAfter == shareAmount && totalBefore - totalAfter == shareAmount));
    }

    function testFuzz_run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes memory data, uint256 deadline) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline);
    }

    receive() external payable {}
}
